package repokit

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/ismoilovdevml/hangar/internal/core"
)

// ReindexDebounce is how long a metadata regeneration job waits after it
// was first enqueued, so a burst of deletes or quarantines (a cleanup
// policy, a bulk quarantine) regenerates a repository's metadata once.
const ReindexDebounce = 2 * time.Second

// ReindexPayload is the payload of a metadata regeneration job.
type ReindexPayload struct {
	RepositoryID string `json:"repository_id"`
}

// EnqueueReindex asks for the metadata of repo to be regenerated by a
// jobType job, coalesced per repository and run on one node. Without a
// job queue (tests, tools) regen runs at once.
func (b *Base) EnqueueReindex(ctx context.Context, jobType string, repo *core.Repository,
	regen func(context.Context, *core.Repository) error) error {
	if b.Deps.Jobs == nil {
		return regen(ctx, repo)
	}
	payload, err := json.Marshal(ReindexPayload{RepositoryID: repo.ID})
	if err != nil {
		return err
	}
	_, err = b.Deps.Jobs.Enqueue(ctx, core.Job{Type: jobType, Key: repo.ID, Debounce: ReindexDebounce, Payload: payload})
	return err
}

// ReindexTarget returns the repository a regeneration job names, if it is
// still a hosted repository of this format, or nil when there is nothing
// to do: a malformed job (logged), or a repository deleted or changed
// since. An error is worth a retry.
func (b *Base) ReindexTarget(ctx context.Context, j core.Job) (*core.Repository, error) {
	var p ReindexPayload
	if err := json.Unmarshal(j.Payload, &p); err != nil || p.RepositoryID == "" {
		b.Log.WarnContext(ctx, "dropping malformed metadata regeneration job", "job_id", j.ID, "err", err)
		return nil, nil
	}
	repo, err := b.Deps.Repos.GetByID(ctx, p.RepositoryID)
	if errors.Is(err, core.ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if repo.Format != b.Format || repo.Type != core.RepoHosted {
		return nil, nil
	}
	return repo, nil
}
